using BenchmarkDotNet.Attributes;
using Marimo.Kotowari;
using Marimo.Kotowari.Core;
using Marimo.Parser;
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Text.Json;

namespace Marimo.Kotowari.Benchmarks;

[MemoryDiagnoser]
public class JsonStreamBenchmarks
{
    private byte[] _input = null!;

    [GlobalSetup]
    public void Setup()
        => _input = File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Data", "test.json"));

    public static void Validate()
    {
        var benchmarks = new JsonStreamBenchmarks();
        benchmarks.Setup();
        using var expected = JsonDocument.Parse(benchmarks._input);
        var stringResult = benchmarks.StringInput();
        AssertEquivalent(expected.RootElement, stringResult);

#if !ORIGINAL_STRING
        var utf8Result = benchmarks.Utf8Input();
        AssertEquivalent(expected.RootElement, utf8Result);
#endif

        var nodeCount = CountNodes(stringResult);
        if (nodeCount != 100_001)
        {
            throw new InvalidOperationException($"Expected 100,001 nodes, got {nodeCount:N0}.");
        }

        var parser = (Parser<JSONObject>)(typeof(JSON).GetField("JObject", BindingFlags.NonPublic | BindingFlags.Static)?.GetValue(null)
            ?? throw new InvalidOperationException("Could not find JSON.JObject for full-consumption validation."));
#if TYPED_DOCUMENT
        var stringInput = Encoding.UTF8.GetString(benchmarks._input);
        var stringParse = parser.Parse(Cursol.FromString(stringInput));
        if (!stringParse.IsSuccess || stringParse.Cursol.Index != stringInput.Length)
        {
            throw new InvalidOperationException($"String parser consumed {stringParse.Cursol.Index} of {stringInput.Length} characters.");
        }
        var utf8Parse = parser.Parse(Cursol.FromUtf8(benchmarks._input));
        if (!utf8Parse.IsSuccess || utf8Parse.Cursol.Index != benchmarks._input.Length)
        {
            throw new InvalidOperationException($"UTF-8 parser consumed {utf8Parse.Cursol.Index} of {benchmarks._input.Length} bytes.");
        }
#elif PREVIOUS
        var previousString = Encoding.UTF8.GetString(benchmarks._input);
        var previousStringParse = parser.Parse(new Cursol(previousString));
        if (!previousStringParse.IsSuccess || previousStringParse.Cursol.Index != previousString.Length)
        {
            throw new InvalidOperationException($"String parser consumed {previousStringParse.Cursol.Index} of {previousString.Length} characters.");
        }
        var previousUtf8Parse = parser.Parse(Cursol.FromUtf8(benchmarks._input));
        if (!previousUtf8Parse.IsSuccess || previousUtf8Parse.Cursol.Index != benchmarks._input.Length)
        {
            throw new InvalidOperationException($"UTF-8 parser consumed {previousUtf8Parse.Cursol.Index} of {benchmarks._input.Length} bytes.");
        }
#else
        var originalString = Encoding.UTF8.GetString(benchmarks._input);
        var originalParse = parser.Parse(new Cursol(originalString));
        if (!originalParse.IsSuccess || originalParse.Cursol.Index != originalString.Length)
        {
            throw new InvalidOperationException($"String parser consumed {originalParse.Cursol.Index} of {originalString.Length} characters.");
        }
#endif

        Console.WriteLine($"Input: {benchmarks._input.Length:N0} bytes; {Encoding.UTF8.GetCharCount(benchmarks._input):N0} characters");
        Console.WriteLine($"The parser result matches System.Text.Json, consumes the full input, and contains {nodeCount:N0} nodes.");
    }

    [Benchmark(Baseline = true)]
    public JSONObject StringInput()
    {
        using var source = new MemoryStream(_input, writable: false);
        using var buffer = new MemoryStream(_input.Length);
        source.CopyTo(buffer);
        var bytes = buffer.GetBuffer().AsSpan(0, checked((int)buffer.Length));
        return JSON.Parse(Encoding.UTF8.GetString(bytes));
    }

#if !ORIGINAL_STRING
    [Benchmark]
    public JSONObject Utf8Input()
    {
        using var source = new MemoryStream(_input, writable: false);
        using var buffer = new MemoryStream(_input.Length);
        source.CopyTo(buffer);
        var bytes = buffer.GetBuffer().AsSpan(0, checked((int)buffer.Length));
        return JSON.Parse(bytes);
    }
#endif

    private static int CountNodes(IJSONValue value)
    {
        if (value is JSONObject obj)
        {
            var count = 1;
            foreach (var child in obj.Pairs.Values) count += CountNodes(child);
            return count;
        }

        if (value is JSONArray array)
        {
            var count = 1;
            foreach (var child in array.Elements) count += CountNodes(child);
            return count;
        }

        return 1;
    }

    private static void AssertEquivalent(JsonElement expected, IJSONValue actual)
    {
        switch (expected.ValueKind)
        {
            case JsonValueKind.Object:
                if (actual is not JSONObject obj) throw new InvalidOperationException("The parser result is not an object.");
                foreach (var property in expected.EnumerateObject())
                {
                    if (!obj.Pairs.TryGetValue(property.Name, out var child)) throw new InvalidOperationException($"The parser result has no '{property.Name}' property.");
                    AssertEquivalent(property.Value, child);
                }
                if (obj.Pairs.Count != expected.EnumerateObject().Count()) throw new InvalidOperationException("The parser result has a different object member count.");
                return;
            case JsonValueKind.Array:
                if (actual is not JSONArray array) throw new InvalidOperationException("The parser result is not an array.");
                var index = 0;
                foreach (var item in expected.EnumerateArray())
                {
                    if (index >= array.Elements.Count) throw new InvalidOperationException("The parser result has too few array elements.");
                    AssertEquivalent(item, array.Elements[index++]);
                }
                if (index != array.Elements.Count) throw new InvalidOperationException("The parser result has too many array elements.");
                return;
            case JsonValueKind.String: AssertLiteral(actual, LiteralType.String, expected.GetString()); return;
            case JsonValueKind.Number: AssertLiteral(actual, LiteralType.Number, expected.GetRawText()); return;
            case JsonValueKind.True: AssertLiteral(actual, LiteralType.Boolean, "true"); return;
            case JsonValueKind.False: AssertLiteral(actual, LiteralType.Boolean, "false"); return;
            case JsonValueKind.Null: AssertLiteral(actual, LiteralType.Null, null); return;
            default: throw new InvalidOperationException($"Unsupported JSON kind: {expected.ValueKind}.");
        }
    }

    private static void AssertLiteral(IJSONValue actual, LiteralType type, string? value)
    {
        if (actual is not JSONLiteral literal || literal.ValueType != type || literal.Value != value)
            throw new InvalidOperationException($"Unexpected JSON literal; expected {type} '{value}'.");
    }
}

Sources.Program:
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Running;

namespace Marimo.Kotowari.Benchmarks;

public static class Program
{
    public static void Main(string[] args)
    {
        if (args is ["--validate"])
        {
            JsonStreamBenchmarks.Validate();
            return;
        }

        var config = DefaultConfig.Instance.WithOptions(ConfigOptions.DisableOptimizationsValidator);
        BenchmarkSwitcher.FromAssembly(typeof(Program).Assembly).Run(args, config);
    }
}
